#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct PseudoElementRemovedEvent {
    /// Pseudo element's parent element id.
    #[serde(rename = "parentId")]
    pub parent_id: NodeId,
    /// The removed pseudo element id.
    #[serde(rename = "pseudoElementId")]
    pub pseudo_element_id: NodeId,
}

impl crate::typed::Event for PseudoElementRemovedEvent {
    const METHOD: &'static str = "DOM.pseudoElementRemoved";
}

/// Fired when backend wants to provide client with the missing DOM structure.
/// This happens upon most of the calls requesting node ids.
///
/// Payload of the `DOM.setChildNodes` event.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct SetChildNodesEvent {
    /// Parent node id to populate with children.
    #[serde(rename = "parentId")]
    pub parent_id: NodeId,
    /// Child nodes array.
    pub nodes: Vec<Node>,
}

impl crate::typed::Event for SetChildNodesEvent {
    const METHOD: &'static str = "DOM.setChildNodes";
}

/// Called when shadow root is popped from the element.
///
/// Experimental: may change without notice.
///
/// Payload of the `DOM.shadowRootPopped` event.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct ShadowRootPoppedEvent {
    /// Host element id.
    #[serde(rename = "hostId")]
    pub host_id: NodeId,
    /// Shadow root id.
    #[serde(rename = "rootId")]
    pub root_id: NodeId,
}

impl crate::typed::Event for ShadowRootPoppedEvent {
    const METHOD: &'static str = "DOM.shadowRootPopped";
}

/// Called when shadow root is pushed into the element.
///
/// Experimental: may change without notice.
///
/// Payload of the `DOM.shadowRootPushed` event.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct ShadowRootPushedEvent {
    /// Host element id.
    #[serde(rename = "hostId")]
    pub host_id: NodeId,
    /// Shadow root.
    pub root: Node,
}

impl crate::typed::Event for ShadowRootPushedEvent {
    const METHOD: &'static str = "DOM.shadowRootPushed";
}
